import os
import re

import pytest

PROJECT = "/project"

SRC_EXTS = {
    ".py", ".sh", ".bash", ".js", ".ts", ".mjs", ".cjs", ".go", ".rs", ".rb",
    ".java", ".kt", ".cs", ".php", ".pl", ".lua", ".ps1", ".mk", ".yml", ".yaml",
}
SKIP_DIRS = {
    ".git", "node_modules", ".venv", "venv", "__pycache__", "dist", "build",
    "docs", "doc", "tests", "test", "__tests__", "site-packages", ".tox",
}

MERGE_CALL = re.compile(r'''(?:git\s+merge\b|["']merge["']|\bmerge\s*\()''')
NO_FF = re.compile(r"--no-ff|no[-_]ff\b|merge\.ff\s*=?\s*false|--ff=false", re.I)
NOT_A_MERGE = re.compile(r"--abort|--continue|--quit|--ff-only|--squash", re.I)
FINISH = re.compile(r"finish", re.I)
FLOW = re.compile(r"release|hotfix", re.I)


def _source_files():
    assert os.path.isdir(PROJECT), f"{PROJECT} is not mounted"
    for root, dirs, files in os.walk(PROJECT):
        dirs[:] = [d for d in dirs if d not in SKIP_DIRS]
        for name in files:
            if os.path.splitext(name)[1].lower() not in SRC_EXTS:
                continue
            if name.startswith("test_") or name.endswith("_test.py"):
                continue
            path = os.path.join(root, name)
            try:
                with open(path, encoding="utf-8", errors="replace") as fh:
                    yield path, fh.read()
            except OSError:
                continue


def _is_comment(line):
    s = line.strip()
    return s.startswith(("#", "//", "*", "/*"))


def test_release_and_hotfix_finish_merge_with_no_ff():
    candidates = []
    for path, text in _source_files():
        if FINISH.search(text) and FLOW.search(text) and MERGE_CALL.search(text):
            candidates.append((path, text))

    assert candidates, (
        "No source file implementing release/hotfix finish with a merge step "
        "was found in /project"
    )

    merges_seen = 0
    violations = []
    for path, text in candidates:
        lines = text.splitlines()
        for i, line in enumerate(lines):
            if _is_comment(line) or not MERGE_CALL.search(line):
                continue
            window = "\n".join(lines[max(0, i - 2): i + 5])
            if NOT_A_MERGE.search(line) and not NO_FF.search(line):
                # explicitly a non-merge helper option, or a forbidden ff-only/squash merge
                if re.search(r"--ff-only|--squash", line, re.I):
                    violations.append(f"{path}:{i + 1}: {line.strip()}")
                continue
            merges_seen += 1
            if not NO_FF.search(window):
                violations.append(f"{path}:{i + 1}: {line.strip()}")

    assert merges_seen, "No merge invocations found in release/hotfix finish code"
    assert not violations, (
        "Merges in release/hotfix finish logic lacking a non-fast-forward "
        "(--no-ff) merge:\n" + "\n".join(violations)
    )
